"""Tests for process normrules command (TDD)."""

import tempfile
from pathlib import Path
from unittest.mock import MagicMock, patch

from oyez_sa_asr.cli import app
from tests.test_cli_process_helpers import runner, strip_ansi


class TestProcessNormrulesHelp:
    """Tests for process normrules help."""

    def test_process_normrules_help(self) -> None:
        """Shows help for process normrules with output/input dir options."""
        result = runner.invoke(app, ["process", "normrules", "--help"])
        assert result.exit_code == 0
        out = strip_ansi(result.output)
        assert "normrules" in out.lower()
        assert "--output-dir" in out or "-o" in out
        assert "--input-dir" in out or "-i" in out


class TestProcessNormrulesScriptsMissing:
    """Tests when project root has no scripts."""

    def test_process_normrules_fails_when_scripts_missing(self) -> None:
        """Exits non-zero with message when scripts are not under project root."""
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            with patch(
                "oyez_sa_asr.cli_process_normrules._project_root",
                return_value=root,
            ):
                result = runner.invoke(
                    app,
                    [
                        "process",
                        "normrules",
                        "--output-dir",
                        str(root / "out"),
                        "--input-dir",
                        str(root / "in"),
                    ],
                )
        assert result.exit_code != 0
        out = strip_ansi(result.output)
        assert "project root" in out.lower() or "scripts" in out.lower()


class TestProcessNormrulesSubprocessCalls:
    """Tests for subprocess invocation of legal dict, rule and awareness scripts."""

    def test_process_normrules_calls_legal_dict_then_rule_and_awareness_scripts(
        self,
    ) -> None:
        """Calls build_legal_dict, then build_rule_candidates, then build_awareness_candidates."""
        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            (root / "scripts").mkdir()
            (root / "scripts" / "build_legal_dict.py").write_text("")
            (root / "scripts" / "build_rule_candidates.py").write_text("")
            (root / "scripts" / "build_awareness_candidates.py").write_text("")
            input_dir = root / "transcripts"
            output_dir = root / "normrules"
            input_dir.mkdir()
            output_dir.mkdir()

            mock_result = MagicMock()
            mock_result.returncode = 0
            with (
                patch(
                    "oyez_sa_asr.cli_process_normrules._project_root",
                    return_value=root,
                ),
                patch(
                    "oyez_sa_asr.cli_process_normrules.subprocess.run",
                    return_value=mock_result,
                ) as run_mock,
            ):
                result = runner.invoke(
                    app,
                    [
                        "process",
                        "normrules",
                        "--output-dir",
                        str(output_dir),
                        "--input-dir",
                        str(input_dir),
                    ],
                )

        assert result.exit_code == 0
        assert run_mock.call_count == 3
        calls = run_mock.call_args_list
        legal_args = calls[0][0][0]
        rule_args = calls[1][0][0]
        awareness_args = calls[2][0][0]
        assert "scripts.build_legal_dict" in legal_args
        assert "scripts.build_rule_candidates" in rule_args
        assert "scripts.build_awareness_candidates" in awareness_args
        assert "-o" in legal_args and str(output_dir / "legal_words.txt") in legal_args
        assert "-i" in rule_args and str(input_dir) in rule_args
        assert "-o" in rule_args and str(output_dir) in rule_args
        assert "-i" in awareness_args and str(input_dir) in awareness_args
        assert "-o" in awareness_args and str(output_dir) in awareness_args
        first_kw = calls[0][1]
        assert first_kw.get("env") and "PYTHONPATH" in first_kw["env"]
        assert str(root) == first_kw["env"]["PYTHONPATH"]
        assert first_kw.get("cwd") == root
        for call in (calls[1], calls[2]):
            legal_path = call[1].get("env", {}).get("LEGAL_WORDS_PATH", "")
            assert legal_path.endswith("legal_words.txt")
